        return report

    def save_report(self, content: str, output_path: str):
        with open(output_path, "w", encoding="utf-8") as f:
            f.write(content)


def stream_print(text: str):
    for char in text:
        sys.stdout.write(char)
        sys.stdout.flush()
    print()


def main():
